resource appGw 'Microsoft.Network/applicationGateways@2023-09-01' = {
  name: appGwName
  location: location
  tags: tags
  zones: zones
  sku: {
    name: 'WAF_v2'
    tier: 'WAF_v2'
  }
  properties: {
    autoscaleConfiguration: {
      minCapacity: appGwMinCapacity
      maxCapacity: appGwMaxCapacity
    }
    enableHttp2: true
    gatewayIPConfigurations: [
      {
        name: 'appGatewayIpConfig'
        properties: {
          subnet: {
            id: '${vnet.id}/subnets/${appGwSubnetName}'
          }
        }
      }
    ]
    frontendIPConfigurations: [
      {
        name: 'publicFrontend'
        properties: {
          publicIPAddress: {
            id: publicIp.id
          }
        }
      }
    ]
    frontendPorts: [
      {
        name: httpPortName
        properties: {
          port: 80
        }
      }
      {
        name: httpsPortName
        properties: {
          port: 443
        }
      }
    ]
    sslCertificates: [
      {
        name: 'sslCert1'
        properties: {
          data: sslCertData
          password: sslCertPassword
        }
      }
    ]
    backendAddressPools: [
      {
        name: backendPoolName
        properties: {
        }
      }
    ]
    backendHttpSettingsCollection: [
      {
        name: httpSettingsName
        properties: {
          port: 80
          protocol: 'Http'
          cookieBasedAffinity: 'Disabled'
          pickHostNameFromBackendAddress: false
          requestTimeout: 30
          probe: {
            id: '${appGw.id}/probes/${probeName}'
          }
        }
      }
    ]
    probes: [
      {
        name: probeName
        properties: {
          protocol: 'Http'
          path: '/'
          interval: 30
          timeout: 30
          unhealthyThreshold: 3
          pickHostNameFromBackendHttpSettings: false
          host: '127.0.0.1'
          port: 80
          match: {
            statusCodes: [
              '200-399'
            ]
          }
        }
      }
    ]
    httpListeners: [
      {
        name: httpListenerName
        properties: {
          frontendIPConfiguration: {
            id: '${appGw.id}/frontendIPConfigurations/publicFrontend'
          }
          frontendPort: {
            id: '${appGw.id}/frontendPorts/${httpPortName}'
          }
          protocol: 'Http'
          requireServerNameIndication: false
        }
      }
      {
        name: httpsListenerName
        properties: {
          frontendIPConfiguration: {
            id: '${appGw.id}/frontendIPConfigurations/publicFrontend'
          }
          frontendPort: {
            id: '${appGw.id}/frontendPorts/${httpsPortName}'
          }
          protocol: 'Https'
          sslCertificate: {
            id: '${appGw.id}/sslCertificates/sslCert1'
          }
          requireServerNameIndication: false
        }
      }
    ]
    redirectConfigurations: [
      {
        name: redirectRuleName
        properties: {
          redirectType: 'Permanent'
          targetListener: {
            id: '${appGw.id}/httpListeners/${httpsListenerName}'
          }
          includePath: true
          includeQueryString: true
        }
      }
    ]
    requestRoutingRules: [
      {
        name: routingRuleHttpsName
        properties: {
          ruleType: 'Basic'
          httpListener: {
            id: '${appGw.id}/httpListeners/${httpsListenerName}'
          }
          backendAddressPool: {
            id: '${appGw.id}/backendAddressPools/${backendPoolName}'
          }
          backendHttpSettings: {
            id: '${appGw.id}/backendHttpSettingsCollection/${httpSettingsName}'
          }
        }
      }
      {
        name: 'routingRuleHttpRedirect'
        properties: {
          ruleType: 'Basic'
          httpListener: {
            id: '${appGw.id}/httpListeners/${httpListenerName}'
          }
          redirectConfiguration: {
            id: '${appGw.id}/redirectConfigurations/${redirectRuleName}'
          }
        }
      }
    ]
    firewallPolicy: {
      id: wafPolicy.id
    }
  }
}

